const char* LookupEnumName(uint32_t value) {
    auto it = kEnumNames.find(value);
    return it == kEnumNames.end() ? nullptr : it->second;
}

std::string FormatBitfield(uint32_t value) {
    if (value == 0) return "0";
    std::string s;
    uint32_t remaining = value;
    for (const auto& flag : kBitFlags) {
        if ((remaining & flag.value) == flag.value) {
            if (!s.empty()) s += " | ";
            s += flag.name;
            remaining &= ~flag.value;
        }
    }
    if (remaining != 0) {
        char buf[16];
        snprintf(buf, sizeof(buf), "0x%X", remaining);
        if (!s.empty()) s += " | ";
        s += buf;
    }
    return s;
}
